* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #253442; background: #e9f1ee; }
body { margin: 0; min-width: 320px; min-height: 100vh; display: grid; place-items: center; padding: 24px 16px; background-color: #e9f1ee; background-image: radial-gradient(#c7d8d2 1.5px, transparent 1.5px); background-size: 22px 22px; }
.page { width: min(100%, 520px); }
.eyebrow, .hint { margin: 0 0 14px; color: #60736f; font-size: 14px; font-weight: 800; letter-spacing: .14em; text-align: center; }
.card { position: relative; display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 22px; padding: 32px; border: 3px solid #253442; border-radius: 8px; background: #fffdf5; box-shadow: 8px 8px 0 #253442; }
.avatar { display: grid; place-items: center; width: 96px; height: 96px; border: 3px solid #253442; background: #f0b65b; box-shadow: inset -8px -8px 0 #d98c49; color: #fffdf5; font-size: 48px; text-shadow: 3px 3px #253442; }
.profile-copy { min-width: 0; }
.editable { display: block; margin: 0; padding: 3px 5px; border: 2px solid transparent; border-radius: 3px; overflow-wrap: anywhere; cursor: text; }
.editable:hover { border-color: #c7d8d2; }
.editable:focus { border-color: #4d887b; outline: 3px solid #c7d8d2; }
h1 { font-size: 25px; line-height: 1.25; }
.title { margin-top: 4px; color: #4d887b; font-size: 17px; font-weight: 750; }
.bio { margin-top: 14px; color: #4d5b62; font-size: 16px; line-height: 1.6; }
.meta { display: flex; align-items: center; gap: 8px; margin: 12px 5px 0; color: #60736f; font-size: 13px; font-weight: 800; letter-spacing: .06em; }
.status-dot { width: 9px; height: 9px; border-radius: 50%; background: #4d887b; }
.divider { color: #c7d8d2; }
.actions { grid-column: 1 / -1; display: flex; gap: 12px; margin-top: 4px; }
.button { min-height: 48px; padding: 10px 16px; border: 2px solid #253442; border-radius: 4px; font: inherit; font-size: 16px; font-weight: 800; cursor: pointer; transition: transform .12s, box-shadow .12s, background-color .12s; }
.button:hover { transform: translateY(-2px); box-shadow: 0 4px 0 #253442; }
.button:active { transform: translateY(2px); box-shadow: none; }
.button:focus-visible { outline: 3px solid #4d887b; outline-offset: 3px; }
.primary { flex: 1; color: #fffdf5; background: #4d887b; }
.primary:hover { background: #3c7367; }
.secondary { color: #253442; background: #fffdf5; }
.secondary:hover { background: #e9f1ee; }
.message { position: absolute; top: 12px; right: 14px; margin: 0; padding: 5px 9px; border: 2px solid #253442; border-radius: 3px; color: #253442; background: #f0b65b; font-size: 14px; font-weight: 800; }
.hint { margin: 22px 0 0; font-size: 12px; }
.hint span { padding: 0 6px; color: #4d887b; }
@media (max-width: 420px) { .card { grid-template-columns: 68px minmax(0, 1fr); gap: 14px; padding: 22px 18px; } .avatar { width: 68px; height: 68px; font-size: 36px; } h1 { font-size: 22px; } .actions { gap: 8px; } .button { padding-inline: 10px; } }

const fields = [...document.querySelectorAll('.editable')];
const bio = document.getElementById('bio');
const count = document.getElementById('bio-count');
const message = document.getElementById('message');
const saveButton = document.getElementById('save');
const cancelButton = document.getElementById('cancel');
let savedValues = fields.map(field => field.textContent);

function updateCount() {
  const length = [...bio.textContent].length;
  count.textContent = `${Math.min(length, 120)} / 120`;
  if (length > 120) {
    bio.textContent = [...bio.textContent].slice(0, 120).join('');
    const selection = window.getSelection();
    const range = document.createRange();
    range.selectNodeContents(bio);
    range.collapse(false);
    selection.removeAllRanges();
    selection.addRange(range);
  }
}

fields.forEach(field => {
  field.addEventListener('input', () => {
    message.hidden = true;
    if (field === bio) updateCount();
  });
  field.addEventListener('keydown', event => {
    if (event.key === 'Enter' && field !== bio) event.preventDefault();
  });
});

saveButton.addEventListener('click', () => {
  savedValues = fields.map(field => field.textContent.trim());
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateCount();
  message.hidden = false;
});

cancelButton.addEventListener('click', () => {
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateCount();
  message.hidden = true;
});

updateCount();
